import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.DX07gj3j.js";const k=JSON.parse('{"title":"Getting started","description":"Run your first WreckCheck scan and understand the release verdict.","frontmatter":{"title":"Getting started","description":"Run your first WreckCheck scan and understand the release verdict."},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md","lastUpdated":1786686832000}'),i={name:"getting-started.md"};function r(o,e,c,d,l,h){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>WreckCheck looks for the conditions that commonly turn an ordinary deployment into a release incident: exposed credentials, unsafe environment files, vulnerable dependencies, risky Docker settings, and missing or failing release checks.</p><p>It scans a project directory and produces a score, a risk level, and actionable findings. The scan stays on your machine; WreckCheck does not send project files anywhere.</p><h2 id="your-first-scan" tabindex="-1">Your first scan <a class="header-anchor" href="#your-first-scan" aria-label="Permalink to &quot;Your first scan&quot;">​</a></h2><p>From the root of a project, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wreckcheck</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>You can also scan a different directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wreckcheck</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./services/api</span></span></code></pre></div><p>The terminal report begins with project detection, then gives the release verdict and groups active findings by severity.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SHIP READINESS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>           84 / 100</span></span>
<span class="line"><span></span></span>
<span class="line"><span>           ✓ SAFE TO SHIP</span></span></code></pre></div><h2 id="read-the-verdict" tabindex="-1">Read the verdict <a class="header-anchor" href="#read-the-verdict" aria-label="Permalink to &quot;Read the verdict&quot;">​</a></h2><p>WreckCheck derives the score and risk level from findings that are active under your policy. Ignored findings remain visible in reports, but do not affect the verdict or CI exit code.</p><table tabindex="0"><thead><tr><th>Verdict</th><th>Trigger</th><th>What to do</th></tr></thead><tbody><tr><td><code>✓ SAFE TO SHIP</code></td><td>Only low or info findings, or none</td><td>Ship with the usual review process.</td></tr><tr><td><code>⚠ REVIEW BEFORE SHIPPING</code></td><td>At least one medium finding</td><td>Resolve or explicitly accept the risk before release.</td></tr><tr><td><code>⚠ HIGH RISK</code></td><td>At least one high finding</td><td>Treat the release as at risk and fix the blocker.</td></tr><tr><td><code>✖ BLOCKED</code></td><td>At least one critical finding</td><td>Do not ship before remediation and any needed credential rotation.</td></tr></tbody></table><h2 id="what-happens-in-a-scan" tabindex="-1">What happens in a scan <a class="header-anchor" href="#what-happens-in-a-scan" aria-label="Permalink to &quot;What happens in a scan&quot;">​</a></h2><ol><li>WreckCheck discovers basic project facts: language, package manager, framework, Git, and Docker usage.</li><li>The checks inspect the working tree concurrently.</li><li>Findings are filtered through <code>.wreckcheck.yml</code>, scored, and rendered for the terminal or CI.</li></ol><p>For the full catalog, see <a href="/wreckcheck/checks">Checks</a>. For a release pipeline, continue to <a href="/wreckcheck/usage">Usage</a>.</p><div class="warning custom-block"><p class="custom-block-title">Verification executes project commands</p><p>In the current release, the verification check runs for recognized projects even without <code>--verify</code>. A Node project can therefore run its <code>lint</code>, <code>test</code>, and <code>build</code> scripts; Go, Rust, and Python projects have analogous commands. Scan only code you trust until this behavior is made properly opt-in.</p></div>`,17)])])}const g=t(i,[["render",r]]);export{k as __pageData,g as default};
